actor WorkQueue {
    private var items: [WorkItem] = []
    private let capacity: Int

    func enqueue(_ item: WorkItem) async {
        precondition(items.count < capacity)
        items.append(item)
    }

    func dequeue() async -> WorkItem {
        precondition(!items.isEmpty)
        return items.removeFirst()
    }
}
```
Invariants: `count ≤ capacity`. `enqueue` blocks if full; `dequeue` blocks if empty. Actor isolation ensures thread safety.

