    db.execute("BEGIN")
    do {
        for step in steps {
            try db.execute(step.sql)
        }
        db.execute("COMMIT")
    } catch {
        for step in steps.reversed() {
            try? db.execute(step.rollback)
        }
        db.execute("ROLLBACK")
        throw error
    }
}
